  "components": {
    "securitySchemes": {
      "ServiceDeskWebhookToken": {
        "type": "apiKey",
        "in": "header",
        "name": "X-ServiceDesk-Token",
        "description": "Webhook token configured as N8N_WEBHOOK_TOKEN in the n8n runtime."
      },
      "ServiceDeskInternalRunbookToken": {
        "type": "apiKey",
        "in": "header",
        "name": "X-ServiceDesk-Internal-Token",
        "description": "Internal n8n-to-n8n runbook token from N8N_INTERNAL_RUNBOOK_TOKEN. Required only for dangerous internal runbooks such as AD password reset."
      }
    },
    "schemas": {
      "OpenApiDocument": {
        "type": "object",
        "description": "OpenAPI 3.1 document."
      },
      "EmailTemplateCatalog": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "schema_version",
          "templates"
        ],
        "properties": {
          "schema_version": {
            "const": "1.0"
          },
          "templates": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/EmailTemplate"
            },
            "minItems": 1
          }
        }
      },
      "EmailTemplate": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "template_id",
          "display_name",
          "subject_template",
          "body_template",
          "required_params",
          "params"
        ],
        "properties": {
          "template_id": {
            "type": "string",
            "pattern": "^[a-z][a-z0-9_.-]*$"
          },
          "display_name": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "subject_template": {
            "type": "string",
            "description": "Plain text subject template with {{paramName}} placeholders."
          },
          "body_template": {
            "type": "string",
            "description": "Plain text body template with {{paramName}} placeholders."
          },
          "required_params": {
            "type": "array",
            "items": {
              "type": "string",
              "pattern": "^[A-Za-z][A-Za-z0-9_.-]*$"
            },
            "uniqueItems": true
          },
          "optional_params": {
            "type": "array",
            "items": {
              "type": "string",
              "pattern": "^[A-Za-z][A-Za-z0-9_.-]*$"
            },
            "uniqueItems": true
          },
          "params": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/EmailTemplateParam"
            },
            "minItems": 1
          }
        }
      },
      "EmailTemplateParam": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "name",
          "type",
          "required",
          "description"
        ],
        "properties": {
          "name": {
            "type": "string",
            "pattern": "^[A-Za-z][A-Za-z0-9_.-]*$"
          },
          "type": {
            "enum": [
              "string",
              "number",
              "boolean"
            ]
          },
          "required": {
            "type": "boolean"
          },
          "description": {
            "type": "string"
          },
          "sensitive": {
            "type": "boolean",
            "default": false,
            "description": "Marks a parameter whose value must not be logged or stored outside the approved business process."
          },
          "pattern": {
            "type": "string"
          },
          "example": {
