          },
          "run_id": {
            "type": "string",
            "pattern": "^run-[a-f0-9]{12}$"
          },
          "wait_id": {
            "type": "string",
            "minLength": 1,
            "pattern": "^wait-[a-f0-9]{12}$"
          },
          "correlation_id": {
            "type": "string",
            "minLength": 1
          },
          "event_type": {
            "type": "string",
            "minLength": 1
          },
          "callback_url": {
            "type": "string",
            "format": "uri",
            "description": "Required when result_transport is http_callback or both. The URL must use http or https, must not contain userinfo credentials, must match ORCHESTRATOR_PUBLIC_URL origin/path in non-local environments, and production environments require https except local/dev loopback or compose-host examples.",
            "x-callback-url-policy": {
              "credentials_allowed": false,
              "production_requires_https": true,
              "orchestrator_public_url_env": "ORCHESTRATOR_PUBLIC_URL",
              "allowed_local_http_hosts": [
                "localhost",
                "127.0.0.1",
                "::1",
                "single-label compose hostnames"
              ]
            }
          },
          "result_transport": {
            "$ref": "#/components/schemas/RunbookResultTransport"
          },
          "result_topic": {
            "type": "string",
            "description": "Required when result_transport is kafka_event or both. Default ServiceDesk local topic is external.events."
          },
          "idempotency_key_base": {
            "type": "string",
            "minLength": 1
          }
        },
        "allOf": [
          {
            "if": {
              "properties": {
                "result_transport": {
                  "const": "http_callback"
                }
              },
              "required": [
                "result_transport"
              ]
            },
            "then": {
              "required": [
                "callback_url"
              ]
            }
          },
          {
            "if": {
              "properties": {
                "result_transport": {
                  "const": "kafka_event"
                }
              },
              "required": [
                "result_transport"
              ]
            },
            "then": {
              "required": [
                "result_topic"
              ]
            }
          },
          {
            "if": {
              "properties": {
                "result_transport": {
                  "const": "both"
                }
              },
              "required": [
                "result_transport"
              ]
            },
            "then": {
              "required": [
                "callback_url",
                "result_topic"
              ]
            }
          }
        ]
      },
      "RunbookResultTransport": {
        "enum": [
          "http_callback",
          "kafka_event",
          "both"
        ]
      },
